/// @file storage_backend.h
/// @brief Abstract interface for specialised storage resolution backends.
///
/// StorageBackend is the type-erased base class used by Storage::Impl.
/// Concrete implementations are generated by StorageBackendImpl<DataTraits, CacheTraits>.
///
/// Internal header — not part of the public include path.
#pragma once

#include "../roots/root.h"
#include "../tables/encoding.h"
#include "data_source.h"
#include "key_utils.h"

#include <whiteout/common_types.h>
#include <whiteout/interfaces.h>
#include <whiteout/storages/casc/storage.h>

#include <array>
#include <optional>
#include <span>
#include <unordered_map>
#include <vector>

namespace whiteout::storages::casc {

// ============================================================================
// Batch type definitions (shared by backend + storage_core)
// ============================================================================

/// Per-request work item for batch resolution.
struct ResolveWork {
    size_t requestIndex;
    std::vector<const RootEntry*> rootEntries;
    u32 localeFlags;
    bool cachedResult = false;
};

/// Resolved BLTE blob ready for batch decode.
struct ResolvedBlob {
    std::vector<u8> blteData;
    std::span<const u8> blteSpan; ///< Local zero-copy (valid while mmap alive).
    bool resolved = false;
    bool useSpan = false;
    std::string error;
};

// ============================================================================
// StorageBackend — abstract interface
// ============================================================================

/// Abstract resolution backend, type-erased at the Storage::Impl boundary.
///
/// Concrete template instantiations provide devirtualised data access
/// and cache operations inside method bodies. The single virtual dispatch
/// at this interface is the only runtime overhead.
class StorageBackend {
public:
    virtual ~StorageBackend() = default;

    // ── Resolution (hot path) ────────────────────────────────────

    /// CKey → encoding → index → BLTE decode → raw file data.
    virtual std::vector<u8> resolveCKey(std::span<const u8, 16> cKey,
                                        interfaces::WorkerPool* pool = nullptr) const = 0;

    /// EKey → index → BLTE decode → raw file data (skip encoding table).
    virtual std::vector<u8> resolveEKey(std::span<const u8, 16> eKey,
                                        interfaces::WorkerPool* pool = nullptr) const = 0;

    /// RootEntry → decoded file data (locale filter + container slicing).
    virtual std::optional<std::vector<u8>> resolveRootEntry(
        const std::vector<const RootEntry*>& entries, u32 localeFlags) const = 0;

    // ── Batch resolution ─────────────────────────────────────────

    /// Phase 0.5/1/3 of readBatch: cache lookup, data fetch, cache store.
    /// Phase 0 (overlay) and Phase 2 (BLTE decode) remain in storage_core.
    virtual void resolveBatch(std::span<ResolveWork> work, std::span<ResolvedBlob> blobs,
                              interfaces::WorkerPool* pool) const = 0;

    // ── Data access (used by loadEncodingAndRoot) ────────────────

    /// Find an entry in the index by EKey prefix.
    virtual std::optional<IndexLocation> findInIndex(std::span<const u8> eKeyPrefix) const = 0;

    /// Fetch BLTE-encoded data from a resolved index location.
    virtual std::vector<u8> fetchBlte(const IndexLocation& loc) const = 0;

    /// Fetch BLTE-encoded data for the given EKey (loose file).
    virtual std::vector<u8> fetchBlte(const std::array<u8, 16>& eKey) const = 0;

    // ── VFS prefetch ─────────────────────────────────────────────

    /// Parallel-resolve VFS sub-manifests (dispatch to local/online path).
    virtual std::unordered_map<u64, std::vector<u8>> prefetchVfs(
        const Storage::Impl& impl, const std::vector<std::array<u8, 16>>& vfsEKeys,
        const std::unordered_map<u64, std::array<u8, 16>>& vfsEKeyToCKey) const = 0;

    // ── Cache management ─────────────────────────────────────────

    virtual void flushCache() = 0;
    virtual bool hasCache() const noexcept = 0;

    // ── Queries ──────────────────────────────────────────────────

    virtual bool isLocal() const noexcept = 0;
    virtual bool isOnline() const noexcept = 0;
};

} // namespace whiteout::storages::casc
